fun groupByFirstAppFrame(dump: String, appPrefix: String): List<Pair<String, Int>> =
    dump.split(Regex("\\n\\s*\\n"))                                          // 1. one record per thread
        .map { it.trim() }
        .filter { record -> " virtual" in record.lineSequence().first() }    // 2. only virtual threads
        .mapNotNull { record ->                                              // 3. its first frame of your code
            record.lines().map { it.trim() }.firstOrNull { it.startsWith("at $appPrefix") }
        }
        .groupingBy { it }.eachCount()                                       // 4. count per frame
        .toList()
        .sortedByDescending { it.second }
